<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import type { Permission } from '../types'
import { checkRoleName, createRole, listPermissions } from '../services/roles'
import { permissionLabel } from '../utils/labels'
const router=useRouter(),name=ref(''),description=ref(''),permissions=ref<Permission[]>([]),permissionIds=ref<number[]>([]),expanded=ref<string[]>([]),loading=ref(true),saving=ref(false),submitted=ref(false),error=ref(''),nameState=ref<'idle'|'checking'|'available'|'duplicate'|'error'>('idle')
let checkTimer:number|undefined
const labels:Record<string,string>={users:'Usuarios y roles',customers:'Clientes',workshops:'Talleres',vehicles:'Vehículos',workorders:'Órdenes de trabajo'}
const icons:Record<string,string>={users:'mdi-account-group-outline',customers:'mdi-account-multiple-outline',workshops:'mdi-storefront-outline',vehicles:'mdi-car-outline',workorders:'mdi-clipboard-text-outline'}
const normalizedName=computed(()=>name.value.trim().replace(/\s+/g,' ')),normalizedDescription=computed(()=>description.value.trim().replace(/\s+/g,' '))
const groups=computed(()=>Object.entries(permissions.value.reduce<Record<string,Permission[]>>((out,p)=>{const key=p.code.split(':')[0];(out[key] ||= []).push(p);return out},{})).map(([key,items])=>({key,label:labels[key]||key,icon:icons[key]||'mdi-shield-outline',items})))
const allSelected=computed(()=>permissions.value.length>0&&permissions.value.every(p=>permissionIds.value.includes(p.id)))
const nameError=computed(()=>submitted.value&&normalizedName.value.length<2?'El nombre del rol es obligatorio.':nameState.value==='duplicate'?'Este nombre de rol ya está registrado.':'')
const permissionsError=computed(()=>submitted.value&&permissionIds.value.length===0?'Selecciona al menos un permiso.':'')
const canSubmit=computed(()=>normalizedName.value.length>=2&&nameState.value==='available'&&permissionIds.value.length>0&&!saving.value)
function groupSelected(group:Permission[]){return group.every(p=>permissionIds.value.includes(p.id))}
function toggleGroup(group:Permission[]){const ids=group.map(p=>p.id);permissionIds.value=groupSelected(group)?permissionIds.value.filter(id=>!ids.includes(id)):[...new Set([...permissionIds.value,...ids])]}
function toggleAll(){permissionIds.value=allSelected.value?[]:permissions.value.map(p=>p.id)}
function hint(p:Permission){return p.code.endsWith(':manage')?'Crear, consultar, editar y eliminar':p.code.endsWith(':write')?'Crear y editar':p.code.endsWith(':read')?'Consultar':p.description}
async function load(){loading.value=true;try{permissions.value=await listPermissions();expanded.value=groups.value.map(g=>g.key)}catch{error.value='No fue posible cargar los permisos del sistema.'}finally{loading.value=false}}
async function validateName(){if(normalizedName.value.length<2){nameState.value='idle';return};nameState.value='checking';try{nameState.value=(await checkRoleName(normalizedName.value)).available?'available':'duplicate'}catch{nameState.value='error'}}
watch(name,()=>{if(checkTimer)window.clearTimeout(checkTimer);nameState.value='idle';checkTimer=window.setTimeout(validateName,350)})
async function submit(){submitted.value=true;if(!canSubmit.value)return;saving.value=true;error.value='';try{await createRole({name:normalizedName.value,description:normalizedDescription.value,permission_ids:permissionIds.value});await router.push({path:'/roles',query:{created:'1'}})}catch(cause:any){if(cause.response?.status===409)nameState.value='duplicate';error.value=cause.response?.status===409?'Este nombre de rol ya está registrado.':'No fue posible crear el rol. Inténtalo nuevamente.'}finally{saving.value=false}}
onMounted(load);onBeforeUnmount(()=>{if(checkTimer)window.clearTimeout(checkTimer)})
</script>
<template>
  <v-container class="create-role-page">
    <header class="page-header"><div class="page-title-icon"><v-icon icon="mdi-shield-plus-outline" size="27"/></div><div><p class="eyebrow">CONFIGURACIÓN DE ACCESO</p><h1>Crear nuevo rol</h1><p>Define la información y los permisos que tendrá este perfil dentro del sistema.</p></div></header>
    <v-alert v-if="error" class="role-error mb-5" variant="tonal" closable @click:close="error=''">{{ error }}</v-alert>
    <form class="role-form" @submit.prevent="submit">
      <section class="role-card"><header class="section-heading"><div class="section-icon"><v-icon icon="mdi-shield-account-outline" size="22"/></div><div><h2>Información del rol</h2><p>Completa los datos principales para identificarlo fácilmente.</p></div></header>
        <v-text-field v-model="name" label="Nombre del rol *" placeholder="Ej. Supervisor de taller" prepend-inner-icon="mdi-shield-outline" variant="outlined" :disabled="saving" :error-messages="nameError" @blur="submitted=true"/>
        <div class="name-status"><template v-if="nameState==='checking'"><v-progress-circular indeterminate size="15" width="2"/>Comprobando disponibilidad…</template><template v-else-if="nameState==='available'"><v-icon icon="mdi-check-circle" size="17"/>Nombre disponible</template><template v-else>Usa un nombre único para el nuevo rol.</template></div>
        <v-textarea v-model="description" label="Descripción (opcional)" placeholder="Describe las responsabilidades principales de este rol." prepend-inner-icon="mdi-text-box-outline" variant="outlined" rows="4" counter="200" maxlength="200" :disabled="saving"/>
        <div class="examples"><v-icon icon="mdi-lightbulb-outline" size="19"/><div><strong>Ejemplos</strong><span>Recepcionista, Técnico de diagnóstico o Supervisor de taller.</span></div></div>
      </section>
      <section class="role-card"><header class="section-heading permissions-heading"><div class="section-icon"><v-icon icon="mdi-key-variant" size="22"/></div><div><h2>Permisos del sistema</h2><p>Selecciona las acciones que podrá realizar este rol.</p></div><v-btn class="select-all" variant="outlined" size="small" :disabled="loading||saving" @click="toggleAll">{{allSelected?'Quitar todo':'Seleccionar todo'}}</v-btn></header>
        <p v-if="permissionsError" class="permissions-error"><v-icon icon="mdi-alert-circle-outline" size="17"/>{{permissionsError}}</p><v-progress-linear v-if="loading" indeterminate color="primary" class="my-8"/>
        <v-expansion-panels v-else v-model="expanded" multiple class="permission-panels"><v-expansion-panel v-for="group in groups" :key="group.key" :value="group.key" class="permission-panel"><v-expansion-panel-title><div class="module-title"><v-icon :icon="group.icon" size="21"/><span>{{group.label}}</span><small>{{group.items.filter(item=>permissionIds.includes(item.id)).length}}/{{group.items.length}}</small></div></v-expansion-panel-title><v-expansion-panel-text><div class="module-actions"><v-checkbox v-for="permission in group.items" :key="permission.id" v-model="permissionIds" :value="permission.id" :disabled="saving" density="compact" hide-details><template #label><span><strong>{{permissionLabel(permission.code)}}</strong><small>{{hint(permission)}}</small></span></template></v-checkbox></div><v-btn class="module-select" variant="text" size="small" :disabled="saving" @click="toggleGroup(group.items)">{{groupSelected(group.items)?'Quitar módulo':'Seleccionar módulo'}}</v-btn></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
      </section>
      <footer class="form-actions"><v-btn class="cancel-button" variant="outlined" :disabled="saving" to="/roles">Cancelar</v-btn><v-btn class="create-button" type="submit" prepend-icon="mdi-plus" :loading="saving">Crear rol</v-btn></footer>
    </form>
  </v-container>
</template>
<style scoped>
